import{_ as a,o as t,c as s,a2 as r}from"./chunks/framework.Cu3jFwFD.js";const g=JSON.parse('{"title":"Trials","description":"","frontmatter":{},"headers":[],"relativePath":"features/trials/design.md","filePath":"features/trials/design.md","lastUpdated":1794907169000}'),n={name:"features/trials/design.md"};function i(d,e,l,o,h,p){return t(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="trials" tabindex="-1">Trials <a class="header-anchor" href="#trials" aria-label="Permalink to &quot;Trials&quot;">​</a></h1><p><strong>Status:</strong> <span class="status-badge status-designed">DESIGNED</span> · <strong>Updated:</strong> 2026-11-17 · <a href="./../../GDD">GDD</a></p><p>Before each normal shift (except Day 1) the player picks one of three trials. A trial sets three dials for that shift: how dangerous the lightning is, how much packages pay and how many packages appear. Danger is the price; value and intensity are the reward. Serves <strong>Push your luck</strong>: the player chooses the day&#39;s risk before driving.</p><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><ol><li><p>Flow of a normal day: Garage → Start → choose a trial → shift → overtime or go home → report → Garage (<a class="decision-ref" href="/hex-gdd/GDD#d-046">D‑046</a>).</p></li><li><p>Day 1 has no choice: it always uses the Standard trial (danger 1, value 2, intensity 2), on every run, so the first day and the tutorial stay readable (<a class="decision-ref" href="/hex-gdd/GDD#d-046">D‑046</a>).</p></li><li><p>The boss day has no trial; it uses its own fixed setup (<a href="./../boss-charon/design">boss-charon</a>) (<a class="decision-ref" href="/hex-gdd/GDD#d-049">D‑049</a>).</p></li><li><p>Each offer shows three trials with three different danger levels (1, 2 and 3), shuffled. Each dial is shown as 1 to 3 pluses with a one-line explanation on hover.</p></li><li><p><strong>Danger</strong> sets the lightning during the shift (<a class="decision-ref" href="/hex-gdd/GDD#d-047">D‑047</a>):</p><ul><li>1: lightning only inside the lightning area around Zeus&#39;s palace and the Electrical Plant.</li><li>2: lightning anywhere on the map, at a low rate.</li><li>3: lightning anywhere on the map, at a busy rate. Overtime&#39;s storm hunts the van at every danger level (<a href="./../day-cycle-and-storm/design">day-cycle-and-storm</a>).</li></ul></li><li><p><strong>Value</strong> multiplies the pay of every package that shift.</p></li><li><p><strong>Intensity</strong> sets how many open pickups the map keeps and how fast new ones appear (<a class="decision-ref" href="/hex-gdd/GDD#d-048">D‑048</a>). It is a reward: more jobs means more money within the 60 s shift.</p></li><li><p><strong>Reward budget</strong> (<a class="decision-ref" href="/hex-gdd/GDD#d-054">D‑054</a>): the reward of a trial is value + intensity, and it is fixed by its danger, so a higher danger always pays more and no trial is strictly worse than another.</p><table tabindex="0"><thead><tr><th>Danger</th><th>Reward budget (value + intensity)</th><th>Possible (value, intensity)</th></tr></thead><tbody><tr><td>1</td><td>3</td><td>(1, 2), (2, 1)</td></tr><tr><td>2</td><td>4</td><td>(1, 3), (2, 2), (3, 1)</td></tr><tr><td>3</td><td>5 or 6, 50/50</td><td>(2, 3), (3, 2), (3, 3)</td></tr></tbody></table><p>Generation, per offer:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dangers = shuffle([1, 2, 3])</span></span>
<span class="line"><span>for d in dangers:</span></span>
<span class="line"><span>    budget = 3 if d == 1 else 4 if d == 2 else random_choice([5, 6])</span></span>
<span class="line"><span>    value  = random_int(max(1, budget - 3), min(3, budget - 1))   # inclusive</span></span>
<span class="line"><span>    intensity = budget - value</span></span>
<span class="line"><span>    offer.add(Trial(d, value, intensity))</span></span></code></pre></div><p>Every dial ends in 1–3. Danger 3 never gets a dial below 2, so &quot;danger +++ with value + and intensity +&quot; cannot happen. The Day 1 Standard trial (1, 2, 2) is a fixed exception and is never rolled.</p></li><li><p><strong>Acceptance:</strong> over 10,000 rolled offers, every offer has dangers {1, 2, 3}; for every trial, value + intensity equals its danger&#39;s budget; reward(danger 3) &gt; reward(danger 2) &gt; reward(danger 1) in every offer.</p></li><li><p>The chosen trial is shown on the HUD during the shift and on the report.</p></li></ol><h2 id="numbers" tabindex="-1">Numbers <a class="header-anchor" href="#numbers" aria-label="Permalink to &quot;Numbers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Value</th><th>Unit</th><th>What to watch in playtests</th></tr></thead><tbody><tr><td>Value multiplier, level 1 / 2 / 3</td><td>×0.75 / ×1.0 / ×1.5 <mark class="tune">TUNE</mark></td><td>factor</td><td>Which danger level players pick most</td></tr><tr><td>Open pickups, intensity 1 / 2 / 3</td><td>4 / 6 / 9 <mark class="tune">TUNE</mark></td><td>jobs</td><td></td></tr><tr><td>New job interval, intensity 1 / 2 / 3</td><td>3.5 / 2.5 / 1.6 <mark class="tune">TUNE</mark></td><td>s</td><td></td></tr><tr><td>Shift lightning per danger level</td><td>see <a href="./../day-cycle-and-storm/design">day-cycle-and-storm</a> rule 2 (<a class="decision-ref" href="/hex-gdd/GDD#d-062">D‑062</a>)</td><td>—</td><td>Danger 3 should hurt but not wreck a careful driver in one shift</td></tr></tbody></table><h2 id="edge-cases" tabindex="-1">Edge cases <a class="header-anchor" href="#edge-cases" aria-label="Permalink to &quot;Edge cases&quot;">​</a></h2><ul><li>A Zeus ward protects the van from shift lightning at every danger level (<a href="./../packages/design">packages</a>).</li><li>On Day 2 Chance packages appear for the first time (<a class="decision-ref" href="/hex-gdd/GDD#d-044">D‑044</a>) whatever the trial.</li><li>The quota is the same whatever trials the player picks; trials change how fast it is reached.</li></ul><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><ul><li><mark class="tune">TUNE</mark> Value and intensity numbers are the prototype&#39;s.</li></ul><h2 id="history" tabindex="-1">History <a class="header-anchor" href="#history" aria-label="Permalink to &quot;History&quot;">​</a></h2><ul><li>2026-11-17: designed (<a class="decision-ref" href="/hex-gdd/GDD#d-046">D‑046</a> to <a class="decision-ref" href="/hex-gdd/GDD#d-049">D‑049</a>), from the owner&#39;s day flow and the prototype&#39;s trial picker. Was an &quot;idea / later&quot; row.</li></ul>`,13)])])}const u=a(n,[["render",i]]);export{g as __pageData,u as default};
